  (("British Virgin Islands", "FSC VASP registration for virtual-asset services; custody/exchange controls.", "Credible digital-asset or holding candidate; VASP registration does not replace fiat remittance authority."), ("جزر العذراء البريطانية", "تسجيل VASP لدى FSC للأصول الافتراضية مع ضوابط للحفظ والصرف.", "مرشح للحفظ الرقمي أو الشركة القابضة؛ تسجيل VASP لا يحل محل إذن الحوالة النقدية.")),
  (("Bermuda", "BMA test, modified and full digital-asset licences; includes digital-asset payment service.", "Clearer institutional regime; higher compliance substance and cost; still needs destination permissions."), ("برمودا", "تراخيص BMA تجريبية ومحدودة وكاملة؛ تشمل دفعاً يستخدم أصلاً رقمياً.", "نظام مؤسسي أوضح لكنه أعلى كلفة والتزاماً؛ ولا يغني عن إذن بلد المستفيد.")),
  (("Cayman Islands", "CIMA licence for custody/trading platform since April 2025; other VASP registration.", "Potential holding or digital-asset base; not a low-control shortcut for payments."), ("جزر كايمان", "ترخيص CIMA للحفظ ومنصات التداول منذ أبريل 2025؛ وتسجيل لباقي VASP.", "ممكن للشركة القابضة أو أصل رقمي؛ ليس طريقاً سهلاً لتجاوز ضوابط الدفع.")),
  (("Seychelles", "FSA VASP Act 2024; Seychelles IBC still needs licence for virtual-asset services.", "Potential specialist VASP base; verify bankability and partner acceptance."), ("سيشل", "قانون FSA لعام 2024؛ حتى شركة IBC تحتاج ترخيص VASP.", "ممكن لنشاط رقمي متخصص؛ يلزم فحص الوصول المصرفي وقبول الشركاء.")),
  (("Mauritius", "FSC virtual-asset licence classes under 2021 Act.", "Non-Caribbean comparison with defined categories; assess substance and fiat payments separately."), ("موريشيوس", "فئات ترخيص الأصول الافتراضية لدى FSC بموجب قانون 2021.", "مقارنة خارج الكاريبي بفئات واضحة؛ تُفحص شروط الحضور والدفع النقدي منفصلة.")),
  (("Mohéli / Mwali", "Comoros central bank says island-issued offshore financial licences are unauthorised; government warned of MISA and non-official crypto/FX licences.", "Reject as a financial-licence route unless Union-level regulator supplies direct written confirmation."), ("موهيلي / موالي", "المصرف المركزي القمري يقول إن تراخيص المال الخارجية الصادرة من الجزر غير مخولة؛ والحكومة حذرت من MISA وتراخيص صرف/كريبتو غير رسمية.", "يُستبعد كمسار ترخيص مالي إلا بتأكيد كتابي مباشر من الجهة الاتحادية المختصة.")),
